CREATE TABLE departments (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, code VARCHAR(20) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employees (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL, department_id BIGINT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_employee_department FOREIGN KEY (department_id) REFERENCES departments(id));
CREATE TABLE service_requests (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, category VARCHAR(40) NOT NULL, priority VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL, requester_id BIGINT NOT NULL, assignee_id BIGINT, department_id BIGINT NOT NULL, due_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT fk_requester FOREIGN KEY (requester_id) REFERENCES employees(id), CONSTRAINT fk_assignee FOREIGN KEY (assignee_id) REFERENCES employees(id), CONSTRAINT fk_request_department FOREIGN KEY (department_id) REFERENCES departments(id), INDEX idx_request_status_created(status, created_at), INDEX idx_request_department(department_id), INDEX idx_request_due(due_at));
CREATE TABLE request_comments (id BIGINT PRIMARY KEY AUTO_INCREMENT, request_id BIGINT NOT NULL, author_id BIGINT NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_comment_request FOREIGN KEY (request_id) REFERENCES service_requests(id) ON DELETE CASCADE, CONSTRAINT fk_comment_author FOREIGN KEY (author_id) REFERENCES employees(id));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, request_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, action VARCHAR(60) NOT NULL, details JSON NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_audit_request FOREIGN KEY (request_id) REFERENCES service_requests(id) ON DELETE CASCADE, CONSTRAINT fk_audit_actor FOREIGN KEY (actor_id) REFERENCES employees(id), INDEX idx_audit_request_created(request_id, created_at));
